int search(int[] nums, int target) {
    int lo = 0, hi = nums.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] == target) return mid;
        else if (nums[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

int mySqrt(int x) {
    if (x < 2) return x;
    int lo = 1, hi = x / 2, ans = 1;
    while (lo <= hi) {
        long mid = lo + (hi - lo) / 2;
        if (mid * mid <= x) {
            ans = (int) mid;
            lo = (int) mid + 1;
        } else {
            hi = (int) mid - 1;
        }
    }
    return ans;
}

int[] searchRange(int[] nums, int target) {
    int first = lowerBound(nums, target);
    if (first == nums.length || nums[first] != target)
        return new int[]{-1, -1};
    int last = upperBound(nums, target) - 1;
    return new int[]{first, last};
}

int lowerBound(int[] nums, int target) {
    int lo = 0, hi = nums.length;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] >= target) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

int upperBound(int[] nums, int target) {
    int lo = 0, hi = nums.length;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] > target) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

int findKthPositive(int[] arr, int k) {
    int lo = 0, hi = arr.length;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        // Missing count before arr[mid] = arr[mid] - (mid+1)
        if (arr[mid] - (mid + 1) >= k) hi = mid;
        else lo = mid + 1;
    }
    // lo elements exist before the kth missing
    return lo + k;
}

int splitArray(int[] nums, int m) {
    int lo = 0, hi = 0;
    for (int n : nums) {
        lo = Math.max(lo, n);   // at least max element
        hi += n;                // at most total sum
    }
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (feasible(nums, mid, m)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

boolean feasible(int[] nums, int limit, int m) {
    int parts = 1, curSum = 0;
    for (int n : nums) {
        if (curSum + n > limit) {
            parts++;
            curSum = n;
            if (parts > m) return false;
        } else {
            curSum += n;
        }
    }
    return true;
}

int aggressiveCows(int[] stalls, int c) {
    Arrays.sort(stalls);
    int lo = 1, hi = stalls[stalls.length-1] - stalls[0];
    while (lo < hi) {
        int mid = lo + (hi - lo + 1) / 2; // upper mid for maximize
        if (canPlace(stalls, c, mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

boolean canPlace(int[] stalls, int c, int minDist) {
    int count = 1, last = stalls[0];
    for (int i = 1; i < stalls.length; i++) {
        if (stalls[i] - last >= minDist) {
            count++;
            last = stalls[i];
            if (count == c) return true;
        }
    }
    return count >= c;
}

int search(int[] nums, int target) {
    int lo = 0, hi = nums.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] == target) return mid;

        if (nums[lo] <= nums[mid]) { // left half sorted
            if (nums[lo] <= target && target < nums[mid])
                hi = mid - 1;
            else
                lo = mid + 1;
        } else { // right half sorted
            if (nums[mid] < target && target <= nums[hi])
                lo = mid + 1;
            else
                hi = mid - 1;
        }
    }
    return -1;
}

int singleNonDuplicate(int[] nums) {
    int lo = 0, hi = nums.length - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        // Ensure mid is even so we compare (mid, mid+1) pair
        if (mid % 2 == 1) mid--;

        if (nums[mid] == nums[mid + 1]) {
            // Pair intact at mid -> single element is to the RIGHT
            lo = mid + 2;
        } else {
            // Pair broken -> single element is at mid or to the LEFT
            hi = mid;
        }
    }
    return nums[lo];
}

boolean searchMatrix(int[][] matrix, int target) {
    int m = matrix.length, n = matrix[0].length;
    int lo = 0, hi = m * n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        int val = matrix[mid / n][mid % n];
        if (val == target) return true;
        else if (val < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return false;
}

int minSubArrayLen(int target, int[] nums) {
    int n = nums.length;
    int[] prefix = new int[n + 1];
    for (int i = 0; i < n; i++) prefix[i+1] = prefix[i] + nums[i];

    int ans = Integer.MAX_VALUE;
    for (int r = 1; r <= n; r++) {
        int need = prefix[r] - target;
        // Find rightmost l where prefix[l] <= need
        int idx = upperBound(prefix, r, need) - 1;
        if (idx >= 0 && prefix[r] - prefix[idx] >= target) {
            ans = Math.min(ans, r - idx);
        }
    }
    return ans == Integer.MAX_VALUE ? 0 : ans;
}

