int shipWithinDays(int[] weights, int days) {
    int lo = 0, hi = 0;
    for (int w : weights) { lo = Math.max(lo, w); hi += w; }

    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (canShip(weights, days, mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

boolean canShip(int[] weights, int days, int cap) {
    int daysNeeded = 1, cur = 0;
    for (int w : weights) {
        if (cur + w > cap) { daysNeeded++; cur = 0; }
        cur += w;
    }
    return daysNeeded <= days;
}

long minimumTime(int[] time, int totalTrips) {
    long lo = 1, hi = (long) Collections.min(
        Arrays.stream(time).boxed().collect(Collectors.toList()))
        * totalTrips;
    while (lo < hi) {
        long mid = lo + (hi - lo) / 2;
        if (countTrips(time, mid) >= totalTrips) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

long countTrips(int[] time, long t) {
    long trips = 0;
    for (int bus : time) trips += t / bus;
    return trips;
}

int smallestDistancePair(int[] nums, int k) {
    Arrays.sort(nums);
    int n = nums.length;
    int lo = 0, hi = nums[n-1] - nums[0];

    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (countPairs(nums, mid) >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

int countPairs(int[] nums, int dist) {
    int count = 0, left = 0;
    for (int right = 1; right < nums.length; right++) {
        while (nums[right] - nums[left] > dist) left++;
        count += right - left;
    }
    return count;
}

int[] bit;
int n;

List<Integer> countSmaller(int[] nums) {
    // Coordinate compression
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    Map<Integer, Integer> rank = new HashMap<>();
    int r = 1;
    for (int v : sorted) if (!rank.containsKey(v)) rank.put(v, r++);
    n = rank.size();
    bit = new int[n + 1];
    Integer[] result = new Integer[nums.length];

    for (int i = nums.length - 1; i >= 0; i--) {
        int rankVal = rank.get(nums[i]);
        result[i] = query(rankVal - 1); // count smaller
        update(rankVal, 1);
    }
    return Arrays.asList(result);
}

void update(int i, int delta) {
    for (; i <= n; i += i & (-i)) bit[i] += delta;
}

int query(int i) {
    int sum = 0;
    for (; i > 0; i -= i & (-i)) sum += bit[i];
    return sum;
}

int kthSmallest(int[][] matrix, int k) {
    int n = matrix.length;
    int lo = matrix[0][0], hi = matrix[n-1][n-1];
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (countLeq(matrix, mid, n) >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

int countLeq(int[][] matrix, int target, int n) {
    int count = 0, col = n - 1;
    for (int row = 0; row < n; row++) {
        while (col >= 0 && matrix[row][col] > target) col--;
        count += col + 1;
    }
    return count;
}

double findMedianSortedArrays(int[] nums1, int[] nums2) {
    if (nums1.length > nums2.length)
        return findMedianSortedArrays(nums2, nums1);
    int m = nums1.length, n = nums2.length;
    int lo = 0, hi = m;

    while (lo <= hi) {
        int i = lo + (hi - lo) / 2;
        int j = (m + n + 1) / 2 - i;

        int maxLeft1  = (i == 0) ? Integer.MIN_VALUE : nums1[i-1];
        int minRight1 = (i == m) ? Integer.MAX_VALUE : nums1[i];
        int maxLeft2  = (j == 0) ? Integer.MIN_VALUE : nums2[j-1];
        int minRight2 = (j == n) ? Integer.MAX_VALUE : nums2[j];

        if (maxLeft1 <= minRight2 && maxLeft2 <= minRight1) {
            if ((m + n) % 2 == 1)
                return Math.max(maxLeft1, maxLeft2);
            return (Math.max(maxLeft1, maxLeft2)
                  + Math.min(minRight1, minRight2)) / 2.0;
        } else if (maxLeft1 > minRight2) {
            hi = i - 1;
        } else {
            lo = i + 1;
        }
    }
    return 0.0;
}

int minimumEffortPath(int[][] heights) {
    int m = heights.length, n = heights[0].length;
    int lo = 0, hi = 1_000_000;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (canReach(heights, m, n, mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

boolean canReach(int[][] h, int m, int n, int effort) {
    boolean[][] visited = new boolean[m][n];
    Queue<int[]> q = new LinkedList<>();
    q.offer(new int[]{0, 0});
    visited[0][0] = true;
    int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};

    while (!q.isEmpty()) {
        int[] cur = q.poll();
        int r = cur[0], c = cur[1];
        if (r == m-1 && c == n-1) return true;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n
                && !visited[nr][nc]
                && Math.abs(h[nr][nc] - h[r][c]) <= effort) {
                visited[nr][nc] = true;
                q.offer(new int[]{nr, nc});
            }
        }
    }
    return false;
}

int lengthOfLIS(int[] nums) {
    List<Integer> tails = new ArrayList<>();
    for (int x : nums) {
        // Find first tail >= x (lower bound)
        int lo = 0, hi = tails.size();
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (tails.get(mid) >= x) hi = mid;
            else lo = mid + 1;
        }
        if (lo == tails.size()) tails.add(x); // extend
        else tails.set(lo, x);                 // replace
    }
    return tails.size();
}

int maxEnvelopes(int[][] envelopes) {
    // Sort: width asc, height desc for same width
    Arrays.sort(envelopes, (a, b) ->
        a[0] == b[0] ? b[1] - a[1] : a[0] - b[0]);

    // LIS on heights
    List<Integer> tails = new ArrayList<>();
    for (int[] env : envelopes) {
        int h = env[1];
        int lo = 0, hi = tails.size();
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (tails.get(mid) >= h) hi = mid;
            else lo = mid + 1;
        }
        if (lo == tails.size()) tails.add(h);
        else tails.set(lo, h);
    }
    return tails.size();
}

int findMaximumXOR(int[] nums) {
    int[][] trie = new int[32 * nums.length][2];
    int trieSize = 1;

    // Insert all numbers
    for (int num : nums) {
        int node = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (trie[node][bit] == 0)
                trie[node][bit] = trieSize++;
            node = trie[node][bit];
        }
    }

    int maxXor = 0;
    for (int num : nums) {
        int node = 0, curXor = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            int want = 1 - bit; // opposite for max XOR
            if (trie[node][want] != 0) {
                curXor |= (1 << i);
                node = trie[node][want];
            } else {
                node = trie[node][bit];
            }
        }
        maxXor = Math.max(maxXor, curXor);
    }
    return maxXor;
}

int[] parent, rank;

int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]);
    return parent[x];
}

boolean union(int x, int y) {
    int px = find(x), py = find(y);
    if (px == py) return false;
    if (rank[px] < rank[py]) { int t = px; px = py; py = t; }
    parent[py] = px;
    if (rank[px] == rank[py]) rank[px]++;
    return true;
}

int minBottleneck(int n, int[][] edges, int u, int v) {
    // Sort edges by weight
    Arrays.sort(edges, (a, b) -> a[2] - b[2]);

    int lo = 0, hi = edges.length - 1, ans = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        // Initialize DSU
        parent = new int[n]; rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        // Add all edges with weight <= edges[mid][2]
        for (int i = 0; i <= mid; i++)
            union(edges[i][0], edges[i][1]);
        if (find(u) == find(v)) { ans = edges[mid][2]; hi = mid - 1; }
        else lo = mid + 1;
    }
    return ans;
}
